import{_ as t,a0 as l,w as o,s as d,ao as c,I as p,x as a,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"汇总你在 Linux 上的命令使用情况 | LCTT x X-CMD","titleTemplate":false,"description":"汇总你在 Linux 上的命令使用情况 | LCTT (202008) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"汇总你在 Linux 上的命令使用情况 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"汇总你在 Linux 上的命令使用情况 | LCTT (202008) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202008/20200716 Summarizing your command usage on Linux","title":"汇总你在 Linux 上的命令使用情况","tag":"202008","desc":""},"relativePath":"202008/20200716 Summarizing your command usage on Linux.md","filePath":"[post].md"}'),r={name:"202008/20200716 Summarizing your command usage on Linux.md"};function h(g,s,k,u,b,y){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="汇总你在-linux-上的命令使用情况" tabindex="-1">汇总你在 Linux 上的命令使用情况 <a class="header-anchor" href="#汇总你在-linux-上的命令使用情况" aria-label="Permalink to “汇总你在 Linux 上的命令使用情况”">​</a></h1><blockquote><p>使用合适的命令，你可以快速了解 Linux 系统上使用的命令以及执行的频率。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202008/14/221303ln67fl62nsfb7nys.jpg" alt=""></p><p>汇总 Linux 系统上使用的命令只需一串相对简单的命令以及几条管道将它们绑定在一起。当你的历史记录缓冲区保留了最近的 1,000 或 2,000 条命令时，总结你的命令活动可能会变得很乏味。这篇文章提供了一种方便的方法来汇总命令的使用情况，并高亮显示最常用的命令。</p><p>首先，请记住，典型的命令历史记录可能看起来像这样。请注意，命令是显示在命令序列号之后，并紧跟其参数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>91  sudo apt-get install ccrypt</span></span>
<span class="line"><span>     ^</span></span>
<span class="line"><span>     +-- command</span></span></code></pre></div><p>请注意，<code>history</code> 命令遵循 <code>HISTSIZE</code> 的设置，这会决定保留多少条命令。可能是 500、1,000 或更多。如果你不喜欢它的设置，那么可以在 <code>.bashrc</code> 或其他启动文件中添加或更改 <code>HISTSIZE</code> 设置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $HISTSIZE</span></span>
<span class="line"><span>1000</span></span>
<span class="line"><span>$ history | wc -l</span></span>
<span class="line"><span>1000</span></span>
<span class="line"><span>$ grep HISTSIZE ~/.bashrc</span></span>
<span class="line"><span># for setting history length see HISTSIZE and HISTFILESIZE in bash(1)</span></span>
<span class="line"><span>HISTSIZE=1000</span></span></code></pre></div><p>记下大量命令的主要好处之一是，它可以让你轻松地重新运行过去使用的命令，而不必重新输入或记住它们。它还能让你轻松地查看你在一个任务中已经做了多少工作。单独使用 <code>history</code> 命令时，你会看到类似下面这样，最早的在最前面：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history</span></span>
<span class="line"><span>    7  vi tasks</span></span>
<span class="line"><span>    8  alias</span></span>
<span class="line"><span>    9  echo $HISTTIMEFORMAT</span></span>
<span class="line"><span>   10  history</span></span>
<span class="line"><span>   11  date</span></span>
<span class="line"><span>   …</span></span></code></pre></div><p>查看最新使用命令需要查看记录的命令的尾部：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history | tail -4</span></span>
<span class="line"><span> 1007  echo $HISTSIZE</span></span>
<span class="line"><span> 1008  history | wc -l</span></span>
<span class="line"><span> 1009  history</span></span>
<span class="line"><span> 1010  history | tail -4</span></span></code></pre></div><p>另外，你可以使用 <code>tail</code> 命令查看 <code>.bash_history</code> 文件的尾部，但是 <code>history</code> 命令显示的数字可以让你输入如 <code>!1010</code> 这样的数字重新运行命令，这点通常更有用。</p><p>要提供已使用命令的汇总（例如 <code>vi</code> 和 <code>echo</code>），你可以首先使用 <code>awk</code> 将命令与 <code>history</code> 中保存的其他信息分隔开来：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history | awk &#39;{print $2}&#39;</span></span>
<span class="line"><span>vi</span></span>
<span class="line"><span>alias</span></span>
<span class="line"><span>echo</span></span>
<span class="line"><span>history</span></span>
<span class="line"><span>date</span></span>
<span class="line"><span>…</span></span></code></pre></div><p>如果你将历史记录中的命令列表传递给 <code>sort</code> 命令以按字母顺序对命令进行分组，那么会得到以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history | awk &#39;{print $2}&#39; | sort</span></span>
<span class="line"><span>7z</span></span>
<span class="line"><span>7z</span></span>
<span class="line"><span>alias</span></span>
<span class="line"><span>apropos</span></span>
<span class="line"><span>cd</span></span>
<span class="line"><span>cd</span></span>
<span class="line"><span>…</span></span></code></pre></div><p>接下来，将 <code>sort</code> 命令的输出传递给 <code>uniq -c</code> ，这将计算每个命令使用了多少次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history | awk &#39;{print $2}&#39; | sort | uniq -c</span></span>
<span class="line"><span>      2 7z</span></span>
<span class="line"><span>      1 alias</span></span>
<span class="line"><span>      2 apropos</span></span>
<span class="line"><span>     38 cd</span></span>
<span class="line"><span>     21 chmod</span></span>
<span class="line"><span>…</span></span></code></pre></div><p>最后，添加第二个 <code>sort</code> 命令按倒序对命令组计数进行排序，这将先列出最常用的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history | awk &#39;{print $2}&#39; | sort | uniq -c | sort -nr</span></span>
<span class="line"><span>    178 ls</span></span>
<span class="line"><span>     95 vi</span></span>
<span class="line"><span>     63 cd</span></span>
<span class="line"><span>     53 sudo</span></span>
<span class="line"><span>     41 more</span></span>
<span class="line"><span>…</span></span></code></pre></div><p>这样可以让你了解使用最多的命令，但不会包括任何你可能故意从历史记录文件中删除的命令，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HISTIGNORE=&quot;pwd:clear:man:history&quot;</span></span></code></pre></div><h3 id="当修改了历史记录格式时" tabindex="-1">当修改了历史记录格式时 <a class="header-anchor" href="#当修改了历史记录格式时" aria-label="Permalink to “当修改了历史记录格式时”">​</a></h3><p>对于默认的历史记录格式，<code>history</code> 命令输出中的第一个字段将是每个命令的序号，第二个字段是使用的命令。因此，上面所有 <code>awk</code> 命令都设置成显示 <code>$2</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias cmds=&#39;history | awk &#39;\\&#39;&#39;{print $2}&#39;\\&#39;&#39; | sort | uniq -c | sort -nr&#39;</span></span></code></pre></div><p>如果你像下面那样将日期和时间添加了到 <code>history</code> 命令中，那么你还必须修改所设置的别名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $HISTTIMEFORMAT</span></span>
<span class="line"><span>%d/%m/%y %T</span></span></code></pre></div><p>这个日期/时间信息有时会很有帮助，但是这意味着你必须在选择 <code>history</code> 命令的第 4 个字段而不是第 2 个字段来汇总命令，因为你的历史记录条目将如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>91  05/07/20 16:37:39 sudo apt-get install ccrypt</span></span>
<span class="line"><span>                       ^</span></span>
<span class="line"><span>                       +-- command</span></span></code></pre></div><p>因此，在将 <code>$2</code> 变为 <code>$4</code> 之后，用于检查 <code>history</code> 命令的别名将改为这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias cmds=&#39;history | awk &#39;\\&#39;&#39;{print $4}&#39;\\&#39;&#39; | sort | uniq -c | sort -nr&#39;</span></span></code></pre></div><p>可将别名保存在 <code>.bashrc</code> 或其他启动文件中，请确保在 <code>$</code> 符号前面插入反斜杠，以便 bash 不会尝试解释 <code>$4</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias cmds=&#39;history | awk &#39;\\&#39;&#39;{print \\$2}&#39;\\&#39;&#39; | uniq -c | sort -nr&#39;</span></span>
<span class="line"><span>alias cmds=&#39;history | awk &#39;\\&#39;&#39;{print \\$4}&#39;\\&#39;&#39; | uniq -c | sort -nr&#39;</span></span></code></pre></div><p>请注意，日期和时间信息与命令本身保存在历史记录文件的不同行中。因此，添加此信息后，bash 历史记录文件的行数将增加一倍，尽管在 <code>history</code> 命令输出时不会：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wc -l .bash_history</span></span>
<span class="line"><span>2000 .bash_history</span></span>
<span class="line"><span>$ history | wc -l</span></span>
<span class="line"><span>1000</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>你可以随时决定要保留多少命令历史记录，哪些命令不值得记录，以使你的命令摘要最有用。</p><hr>`,39)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),i(n,{href:"https://www.networkworld.com/article/3567050/summarizing-your-command-usage-on-linux.html"},{default:e(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3567050/summarizing-your-command-usage-on-linux.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),i(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:e(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:e(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=t(r,[["render",h]]);export{x as __pageData,C as default};
